import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def solve():
    solutions = []
    max_n = 500

    for n in range(1, max_n + 1):
        tau_n = tau(n)

        if tau_n < 5:
            continue

        divisors = get_divisors(n)

        # We need at least 5 divisors, so divisors[4] exists.
        if len(divisors) < 5:
            continue

        # d1=1, d2=a, d3=b, d4, d5=c
        a = divisors[1]
        b = divisors[2]
        c = divisors[4]

        # Check the condition: n = ab + ac + bc
        # which is equivalent to (a + b + c)^2 = a^2 + b^2 + c^2 + 2n

        required_n = a * b + a * c + b * c

        if required_n == n:
            solutions.append((n, tau_n, a, b, c))

    print("Found solutions (n, tau(n), a, b, c):")
