import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

solutions_to_check = [36, 56, 135]
results = {}

for n in solutions_to_check:
    divs = get_divisors(n)

    if len(divs) < 5:
        results[n] = "Failed: Less than 5 divisors."
        continue

    # Check divisor ordering
    a = divs[1] # 2nd smallest (index 1)
    b = divs[2] # 3rd smallest (index 2)
    c = divs[4] # 5th smallest (index 4)

    # Check equation: n = ab + ac + bc
    check = (a * b + a * c + b * c) == n

    if check:
        ordering_ok = True
        if a != divs[1] or b != divs[2] or c != divs[4]:
             ordering_ok = False # Should not happen based on indexing

        results[n] = {
            "a": a, 
            "b": b, 
            "c": c, 
            "ordering_ok": ordering_ok, 
            "equation_holds": check
        }
    else:
        results[n] = {"equation_holds": False}

print("Verification Results:")
for n, res in results.items():
    print(f"N={n}: {res}")

